# qBitLauncher.ps1

param(
    [string]$filePathFromQB,
    [string]$torrentHashFromQB,
    [string]$torrentNameFromQB
)

# ---- Bundled from Source/Services.ps1 ----
# Side-effect-free definitions for settings, user state, logging and job coordination.
function Get-AppDataDirectory {
    $override = Get-Variable -Name DataDirectory -Scope Global -ValueOnly -ErrorAction SilentlyContinue
    if (-not [string]::IsNullOrWhiteSpace($override)) {
        return [IO.Path]::GetFullPath($override)
    }
    if (-not [string]::IsNullOrWhiteSpace($env:QBITLAUNCHER_DATA_DIRECTORY)) {
        return [IO.Path]::GetFullPath($env:QBITLAUNCHER_DATA_DIRECTORY)
    }
    $base = [Environment]::GetFolderPath('LocalApplicationData')
    if ([string]::IsNullOrWhiteSpace($base)) { throw 'The current user has no local application data directory.' }
    return Join-Path $base 'qBitLauncher'
}

function ConvertTo-SettingsHashtable {
    param($Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [System.Collections.IDictionary]) {
        $result = @{}
        foreach ($key in $Value.Keys) { $result[[string]$key] = ConvertTo-SettingsHashtable $Value[$key] }
        return $result
    }
    if ($Value -is [System.Management.Automation.PSCustomObject]) {
        $result = @{}
        foreach ($property in $Value.PSObject.Properties) { $result[$property.Name] = ConvertTo-SettingsHashtable $property.Value }
        return $result
    }
    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        $result = New-Object System.Collections.ArrayList
        foreach ($entry in $Value) { [void]$result.Add((ConvertTo-SettingsHashtable $entry)) }
        return ,$result.ToArray()
    }
    return $Value
}

function New-DefaultUserSettings {
    return @{
        Theme = 'Dracula'
        QbittorrentWebUrl = 'http://localhost:8080'
        QbittorrentUsername = ''
        QbittorrentPassword = ''
        FilePreferences = @{}
        RecentFolders = @()
        LastExtractionPath = ''
        DefaultAdmin = $true
        CheckForUpdates = $true
        LastUpdateCheckUtc = ''
        WindowState = @{}
    }
}

function Protect-AppSecret {
    param([AllowEmptyString()][string]$Value)
    if ([string]::IsNullOrEmpty($Value)) { return '' }
    Add-Type -AssemblyName System.Security -ErrorAction Stop
    $bytes = [Text.Encoding]::UTF8.GetBytes($Value)
    $entropy = [Text.Encoding]::UTF8.GetBytes('qBitLauncher.settings.v1')
    try {
        $protected = [Security.Cryptography.ProtectedData]::Protect($bytes, $entropy, [Security.Cryptography.DataProtectionScope]::CurrentUser)
        return 'dpapi:v1:' + [Convert]::ToBase64String($protected)
    }
    finally { [Array]::Clear($bytes, 0, $bytes.Length) }
}

function Unprotect-AppSecret {
    param([AllowEmptyString()][string]$Value)
    if ([string]::IsNullOrEmpty($Value)) { return '' }
    if (-not $Value.StartsWith('dpapi:v1:', [StringComparison]::Ordinal)) { throw 'Unrecognized saved credential format.' }
    Add-Type -AssemblyName System.Security -ErrorAction Stop
    $entropy = [Text.Encoding]::UTF8.GetBytes('qBitLauncher.settings.v1')
    $bytes = [Security.Cryptography.ProtectedData]::Unprotect([Convert]::FromBase64String($Value.Substring(9)), $entropy, [Security.Cryptography.DataProtectionScope]::CurrentUser)
    try { return [Text.Encoding]::UTF8.GetString($bytes) }
    finally { [Array]::Clear($bytes, 0, $bytes.Length) }
}

function Get-ServiceKeyHash {
    param([string]$Value)
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return [BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Value))).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
}

function Get-UserSettings {
    $defaults = New-DefaultUserSettings
    $Global:PasswordDecryptionFailed = $false
    $Global:ProtectedSettingsPassword = ''
    $migratePassword = $false
    if ([string]::IsNullOrWhiteSpace($Global:ConfigFile)) {
        $Global:ConfigFile = Join-Path (Get-AppDataDirectory) 'config.json'
    }
    if ([IO.File]::Exists($Global:ConfigFile)) {
        try {
            $loaded = ConvertTo-SettingsHashtable ([IO.File]::ReadAllText($Global:ConfigFile, [Text.Encoding]::UTF8) | ConvertFrom-Json)
            if ($loaded -isnot [System.Collections.IDictionary]) { throw 'Settings must be a JSON object.' }
            foreach ($key in $loaded.Keys) { $defaults[$key] = $loaded[$key] }
            if ($loaded.Contains('QbittorrentPasswordProtected') -and -not [string]::IsNullOrEmpty($loaded.QbittorrentPasswordProtected)) {
                $Global:ProtectedSettingsPassword = [string]$loaded.QbittorrentPasswordProtected
                try { $defaults.QbittorrentPassword = Unprotect-AppSecret $Global:ProtectedSettingsPassword }
                catch {
                    $Global:PasswordDecryptionFailed = $true
                    $defaults.QbittorrentPassword = ''
                    Write-LogMessage 'The saved API credential could not be decrypted for this Windows user. Re-enter it in Settings.'
                }
            }
            elseif ($loaded.Contains('QbittorrentPassword')) { $migratePassword = $true }
        }
        catch { Write-LogMessage ('Settings could not be loaded; using defaults. ' + $_.Exception.GetType().Name) }
    }
    foreach ($key in @('FilePreferences', 'WindowState')) {
        if ($defaults[$key] -isnot [System.Collections.IDictionary]) { $defaults[$key] = @{} }
    }
    if ($null -eq $defaults.RecentFolders -or $defaults.RecentFolders -is [string]) {
        $defaults.RecentFolders = @($defaults.RecentFolders | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    }
    if ([string]::IsNullOrWhiteSpace($defaults.QbittorrentWebUrl)) { $defaults.QbittorrentWebUrl = 'http://localhost:8080' }
    $Global:UserSettings = $defaults
    $themes = Get-Variable -Name Themes -Scope Global -ValueOnly -ErrorAction SilentlyContinue
    if ($themes -is [System.Collections.IDictionary]) {
        if (-not $themes.Contains($defaults.Theme)) { $defaults.Theme = 'Dracula' }
        $Global:ThemeSelection = $defaults.Theme
        $Global:CurrentTheme = $themes[$defaults.Theme]
    }
    $Global:SettingsBaseline = ConvertTo-SettingsHashtable $defaults
    $Global:SettingsBaselinePath = [IO.Path]::GetFullPath($Global:ConfigFile)
    if ($migratePassword) { $null = Save-UserSettings }
}

function Merge-SettingsChanges {
    param([System.Collections.IDictionary]$Latest, [System.Collections.IDictionary]$Baseline, [System.Collections.IDictionary]$Current)
    $merged = ConvertTo-SettingsHashtable $Latest
    foreach ($key in $Baseline.Keys) { if (-not $Current.Contains($key)) { $merged.Remove($key) } }
    foreach ($key in $Current.Keys) {
        if ($Current[$key] -is [System.Collections.IDictionary]) {
            $old = if ($Baseline[$key] -is [System.Collections.IDictionary]) { $Baseline[$key] } else { @{} }
            $disk = if ($merged[$key] -is [System.Collections.IDictionary]) { $merged[$key] } else { @{} }
            $merged[$key] = Merge-SettingsChanges -Latest $disk -Baseline $old -Current $Current[$key]
        }
        elseif (-not $Baseline.Contains($key) -or (ConvertTo-Json -InputObject $Current[$key] -Depth 32 -Compress) -cne (ConvertTo-Json -InputObject $Baseline[$key] -Depth 32 -Compress)) {
            if ($key -eq 'RecentFolders') {
                $removed = @($Baseline[$key] | Where-Object { $_ -notin $Current[$key] })
                $folders = New-Object 'System.Collections.Generic.List[string]'
                foreach ($entry in @($Current[$key]) + @($merged[$key])) {
                    if ($entry -and $entry -notin $removed -and $entry -notin $folders -and $folders.Count -lt 12) { $folders.Add($entry) }
                }
                $merged[$key] = $folders.ToArray()
            } else { $merged[$key] = $Current[$key] }
        }
    }
    return $merged
}

function Save-UserSettings {
    $mutex = $null
    $locked = $false
    $temporary = $null
    try {
        if ([string]::IsNullOrWhiteSpace($Global:ConfigFile)) { $Global:ConfigFile = Join-Path (Get-AppDataDirectory) 'config.json' }
        $path = [IO.Path]::GetFullPath($Global:ConfigFile)
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path)) | Out-Null
        $mutex = New-Object Threading.Mutex($false, ('Local\qBitLauncher.Settings.' + (Get-ServiceKeyHash $path.ToLowerInvariant())))
        try { $locked = $mutex.WaitOne(5000) }
        catch [Threading.AbandonedMutexException] { $locked = $true }
        if (-not $locked) { throw 'Settings are busy in another qBitLauncher process.' }
        $saved = ConvertTo-SettingsHashtable $Global:UserSettings
        if ($saved -isnot [System.Collections.IDictionary]) { throw 'No settings object is available.' }
        $password = [string]$saved.QbittorrentPassword
        $saved.Remove('QbittorrentPassword')
        $saved.Remove('QbittorrentPasswordProtected')
        $latest = @{}
        if ([IO.File]::Exists($path)) { $latest = ConvertTo-SettingsHashtable ([IO.File]::ReadAllText($path, [Text.Encoding]::UTF8) | ConvertFrom-Json) }
        $hasBaseline = $Global:SettingsBaseline -is [System.Collections.IDictionary] -and $Global:SettingsBaselinePath -eq $path
        if ($hasBaseline) {
            $baseline = ConvertTo-SettingsHashtable $Global:SettingsBaseline
            $baseline.Remove('QbittorrentPassword'); $baseline.Remove('QbittorrentPasswordProtected')
            $saved = Merge-SettingsChanges -Latest $latest -Baseline $baseline -Current $saved
        }
        $saved.Remove('QbittorrentPassword')
        if ($hasBaseline -and $password -ceq [string]$Global:SettingsBaseline.QbittorrentPassword -and $latest.Contains('QbittorrentPasswordProtected')) {
            $saved.QbittorrentPasswordProtected = $latest.QbittorrentPasswordProtected
        }
        elseif (-not [string]::IsNullOrEmpty($password)) {
            $saved.QbittorrentPasswordProtected = Protect-AppSecret $password
            $Global:PasswordDecryptionFailed = $false
        }
        elseif ($Global:PasswordDecryptionFailed -and -not [string]::IsNullOrEmpty($Global:ProtectedSettingsPassword)) {
            # Moving portable settings to a different Windows account must not erase ciphertext.
            $saved.QbittorrentPasswordProtected = $Global:ProtectedSettingsPassword
        }
        else { $saved.QbittorrentPasswordProtected = '' }
        $temporary = Join-Path ([IO.Path]::GetDirectoryName($path)) ('.qbit-settings-' + [Guid]::NewGuid().ToString('N') + '.tmp')
        [IO.File]::WriteAllText($temporary, ($saved | ConvertTo-Json -Depth 32), (New-Object Text.UTF8Encoding($false)))
        if ([IO.File]::Exists($path)) { [IO.File]::Replace($temporary, $path, [NullString]::Value) }
        else { [IO.File]::Move($temporary, $path) }
        $Global:ProtectedSettingsPassword = $saved.QbittorrentPasswordProtected
        $Global:SettingsBaseline = ConvertTo-SettingsHashtable $Global:UserSettings
        $Global:SettingsBaselinePath = $path
        return $true
    }
    catch {
        Write-LogMessage ('Settings could not be saved. ' + $_.Exception.GetType().Name)
        return $false
    }
    finally {
        if ($temporary -and [IO.File]::Exists($temporary)) { [IO.File]::Delete($temporary) }
        if ($locked -and $mutex) { $mutex.ReleaseMutex() }
        if ($mutex) { $mutex.Dispose() }
    }
}

function Protect-LogText {
    param([AllowEmptyString()][string]$Text)
    if ($null -eq $Text) { return '' }
    $settings = Get-Variable -Name UserSettings -Scope Global -ValueOnly -ErrorAction SilentlyContinue
    if ($settings -is [System.Collections.IDictionary]) {
        foreach ($key in @('QbittorrentPassword', 'QbittorrentPasswordProtected', 'QbittorrentUsername')) {
            $secret = [string]$settings[$key]
            if (-not [string]::IsNullOrEmpty($secret)) { $Text = $Text.Replace($secret, '[redacted]') }
        }
    }
    $Text = [regex]::Replace($Text, '(?i)(password|token|authorization)(\s*[:=]\s*)([^\r\n,;]+)', '$1$2[redacted]')
    $Text = [regex]::Replace($Text, '(?i)(https?://)[^/@\s]+:[^/@\s]+@', '$1[redacted]@')
    return $Text
}

function Get-AppLogPath {
    $override = Get-Variable -Name LogFile -ValueOnly -ErrorAction SilentlyContinue
    if (-not [string]::IsNullOrWhiteSpace($override)) { return [IO.Path]::GetFullPath($override) }
    return Join-Path (Join-Path (Get-AppDataDirectory) 'logs') 'qBitLauncher.log'
}

function Write-LogMessage {
    param([AllowEmptyString()][string]$Message)
    $mutex = $null
    $locked = $false
    try {
        $path = Get-AppLogPath
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path)) | Out-Null
        $safeMessage = Protect-LogText $Message
        if ($safeMessage.Length -gt 32768) { $safeMessage = $safeMessage.Substring(0, 32768) + ' [truncated]' }
        $entry = [DateTime]::Now.ToString('yyyy-MM-dd HH:mm:ss.fff') + ' [' + $PID + '] ' + $safeMessage + [Environment]::NewLine
        $encoding = New-Object Text.UTF8Encoding($false)
        $maxBytes = 2MB
        $override = Get-Variable -Name LogMaxBytes -Scope Global -ValueOnly -ErrorAction SilentlyContinue
        if ($override -and [long]$override -ge 128) { $maxBytes = [long]$override }
        $mutex = New-Object Threading.Mutex($false, ('Local\qBitLauncher.Log.' + (Get-ServiceKeyHash $path.ToLowerInvariant())))
        try { $locked = $mutex.WaitOne(1500) }
        catch [Threading.AbandonedMutexException] { $locked = $true }
        if (-not $locked) { return }
        if ([IO.File]::Exists($path) -and ((Get-Item -LiteralPath $path).Length + $encoding.GetByteCount($entry)) -gt $maxBytes) {
            if ([IO.File]::Exists($path + '.3')) { [IO.File]::Delete($path + '.3') }
            for ($archive = 2; $archive -ge 1; $archive--) {
                if ([IO.File]::Exists($path + '.' + $archive)) { [IO.File]::Move($path + '.' + $archive, $path + '.' + ($archive + 1)) }
            }
            [IO.File]::Move($path, $path + '.1')
        }
        [IO.File]::AppendAllText($path, $entry, $encoding)
    }
    catch { } # Logging must never block an app action with an error dialog.
    finally {
        if ($locked -and $mutex) { $mutex.ReleaseMutex() }
        if ($mutex) { $mutex.Dispose() }
    }
}

function Get-PreferencePathKey {
    param([Parameter(Mandatory = $true)][string]$Path)
    return (Get-NormalizedServicePath $Path).ToLowerInvariant()
}

function Get-NormalizedServicePath {
    param([Parameter(Mandatory = $true)][string]$Path)
    $fullPath = [IO.Path]::GetFullPath($Path)
    $root = [IO.Path]::GetPathRoot($fullPath)
    if ($fullPath.Length -gt $root.Length) { $fullPath = $fullPath.TrimEnd([char]92, [char]47) }
    return $fullPath
}

function Get-FilePreference {
    param([Parameter(Mandatory = $true)][string]$Path)
    $key = Get-PreferencePathKey $Path
    if ($Global:UserSettings.FilePreferences.Contains($key)) { return ConvertTo-SettingsHashtable $Global:UserSettings.FilePreferences[$key] }
    return @{}
}

function Set-FilePreference {
    param([Parameter(Mandatory = $true)][string]$Path, [Parameter(Mandatory = $true)][hashtable]$Preference)
    $key = Get-PreferencePathKey $Path
    $merged = Get-FilePreference $Path
    foreach ($field in $Preference.Keys) { $merged[$field] = $Preference[$field] }
    $Global:UserSettings.FilePreferences[$key] = $merged
    return Save-UserSettings
}

function Remove-FilePreference {
    param([Parameter(Mandatory = $true)][string]$Path)
    $Global:UserSettings.FilePreferences.Remove((Get-PreferencePathKey $Path))
    return Save-UserSettings
}

function Add-RecentFolder {
    param([Parameter(Mandatory = $true)][string]$Path)
    $fullPath = Get-NormalizedServicePath $Path
    $folders = New-Object System.Collections.Generic.List[string]
    $folders.Add($fullPath)
    foreach ($entry in $Global:UserSettings.RecentFolders) {
        if (-not [string]::IsNullOrWhiteSpace($entry) -and -not [string]::Equals($entry, $fullPath, [StringComparison]::OrdinalIgnoreCase) -and $folders.Count -lt 12) {
            $folders.Add($entry)
        }
    }
    $Global:UserSettings.RecentFolders = $folders.ToArray()
    return Save-UserSettings
}

function Remove-RecentFolder {
    param([Parameter(Mandatory = $true)][string]$Path)
    $Global:UserSettings.RecentFolders = @($Global:UserSettings.RecentFolders | Where-Object { -not [string]::Equals($_, $Path, [StringComparison]::OrdinalIgnoreCase) })
    return Save-UserSettings
}

function New-WorkflowLock {
    param([Parameter(Mandatory = $true)][string]$Key)
    # Only the same source is exclusive. Different games never share a slot.
    $directory = Join-Path (Get-AppDataDirectory) 'workflows'
    [IO.Directory]::CreateDirectory($directory) | Out-Null
    $normalizedKey = $Key.Trim().ToLowerInvariant()
    if ([IO.Path]::IsPathRooted($Key)) { $normalizedKey = Get-PreferencePathKey $Key }
    $lockPath = Join-Path $directory ((Get-ServiceKeyHash $normalizedKey) + '.lock')
    $lock = [pscustomobject]@{ Duplicate = $false; Handle = $null; IsDisposed = $false }
    try { $lock.Handle = [IO.File]::Open($lockPath, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, [IO.FileShare]::None) }
    catch [IO.IOException] { $lock.Duplicate = $true }
    return $lock
}

function Exit-WorkflowLock {
    param([AllowNull()]$Lock)
    if ($null -eq $Lock -or $Lock.IsDisposed) { return }
    if ($Lock.Handle) { $Lock.Handle.Dispose(); $Lock.Handle = $null }
    $Lock.IsDisposed = $true
    # Keep the empty file: removing its path could race the next owner.
}

# ---- Bundled from Source/Updates.ps1 ----
# Release metadata and Unicode-safe update handoff. Definitions only: safe to import.
function Get-UpdateReleaseInfo {
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    return Invoke-RestMethod -Uri 'https://api.github.com/repos/DeonHolo/qBitLauncher/releases/latest' -Headers @{ 'User-Agent' = 'qBitLauncher'; Accept = 'application/vnd.github+json' } -UseBasicParsing -TimeoutSec 10 -ErrorAction Stop
}

function Get-ReleaseUpdateCandidate {
    param([Parameter(Mandatory = $true)]$Release, [bool]$IsCompiled = $Global:IsCompiledExe)

    if ($Release.draft -or $Release.prerelease) { return $null }
    $version = $null
    if (-not [Version]::TryParse(([string]$Release.tag_name -replace '^[vV]', ''), [ref]$version)) { return $null }
    $assetName = if ($IsCompiled) { 'qBitLauncher.exe' } else { 'qBitLauncher.ps1' }
    $asset = @($Release.assets | Where-Object { $_.name -ceq $assetName }) | Select-Object -First 1
    $sums = @($Release.assets | Where-Object { $_.name -ceq 'SHA256SUMS.txt' }) | Select-Object -First 1
    $url = if ($asset) { [string]$asset.browser_download_url } else { '' }
    if (-not $asset -and -not $IsCompiled -and $sums) {
        $url = 'https://raw.githubusercontent.com/DeonHolo/qBitLauncher/' + [Uri]::EscapeDataString([string]$Release.tag_name) + '/qBitLauncher.ps1'
    }
    if ([string]::IsNullOrWhiteSpace($url)) { return $null }
    if ($url -notmatch '^https://github\.com/DeonHolo/qBitLauncher/releases/download/' -and
        $url -notmatch '^https://raw\.githubusercontent\.com/DeonHolo/qBitLauncher/') {
        throw 'The release asset URL is outside the configured repository.'
    }
    $hash = $null
    if ($asset -and ([string]$asset.digest -match '^sha256:([a-fA-F0-9]{64})$')) { $hash = $Matches[1].ToLowerInvariant() }
    return [pscustomobject]@{
        Version = $version.ToString(); Tag = [string]$Release.tag_name; AssetName = $assetName
        DownloadUrl = $url; SHA256 = $hash; ChecksumsUrl = $(if ($sums) { [string]$sums.browser_download_url } else { $null })
        ReleaseUrl = [string]$Release.html_url
    }
}

function Get-RemoteVersion {
    try {
        $release = Get-UpdateReleaseInfo
        $candidate = Get-ReleaseUpdateCandidate -Release $release
        $Global:AvailableUpdate = $candidate
        if ($candidate) { return $candidate.Version }
    }
    catch { Write-LogMessage "Failed to check release updates: $($_.Exception.Message)" }
    return $null
}

function Test-UpdateAvailable {
    $version = Get-RemoteVersion
    if ($version -and [Version]$version -gt [Version]$Global:ScriptVersion) { return $version }
    return $null
}

function Start-BackgroundUpdateCheck {
    param([switch]$Force)
    if ($env:QBITLAUNCHER_SKIP_UPDATE_CHECK -eq '1') { return $null }
    if (-not $Force -and $Global:UserSettings -and $Global:UserSettings.ContainsKey('CheckForUpdates') -and -not $Global:UserSettings.CheckForUpdates) { return $null }
    if (-not $Force -and $Global:UserSettings -and $Global:UserSettings.LastUpdateCheckUtc) {
        $last = [DateTime]::MinValue
        if ([DateTime]::TryParse([string]$Global:UserSettings.LastUpdateCheckUtc, [ref]$last) -and $last.ToUniversalTime().AddHours(12) -gt [DateTime]::UtcNow) { return $null }
    }
    $powerShell = [PowerShell]::Create()
    try {
        $code = ${function:Get-UpdateReleaseInfo}.ToString()
        $null = $powerShell.AddScript($code)
        $handle = $powerShell.BeginInvoke()
        return [pscustomobject]@{ PowerShell = $powerShell; Handle = $handle; Disposed = $false; Result = $null }
    }
    catch { $powerShell.Dispose(); Write-LogMessage "Could not start background update check: $($_.Exception.Message)"; return $null }
}

function Receive-BackgroundUpdateCheck {
    param($Check)
    if (-not $Check) { return $null }
    if ($Check.Disposed) { return $Check.Result }
    if (-not $Check.Handle.IsCompleted) { return $null }
    $result = [pscustomobject]@{ Completed = $true; Version = $null; Error = $null; Release = $null }
    try {
        $items = $Check.PowerShell.EndInvoke($Check.Handle)
        if ($Check.PowerShell.HadErrors) { throw ($Check.PowerShell.Streams.Error | Select-Object -First 1) }
        $release = @($items) | Select-Object -First 1
        if (-not $release) { throw 'GitHub did not return release metadata.' }
        $candidate = Get-ReleaseUpdateCandidate -Release $release
        $Global:AvailableUpdate = $candidate
        $result.Release = $release
        if ($candidate -and [Version]$candidate.Version -gt [Version]$Global:ScriptVersion) { $result.Version = $candidate.Version }
        if ($Global:UserSettings) {
            $Global:UserSettings.LastUpdateCheckUtc = [DateTime]::UtcNow.ToString('o')
            $null = Save-UserSettings
        }
    }
    catch { $result.Error = $_.Exception.Message; Write-LogMessage "Background update check failed: $($result.Error)" }
    finally { $Check.PowerShell.Dispose(); $Check.Disposed = $true }
    $Check.Result = $result
    return $result
}

function Stop-BackgroundUpdateCheck {
    param($Check)
    if ($Check -and -not $Check.Disposed) {
        try { $Check.PowerShell.Stop() } catch { }
        $Check.PowerShell.Dispose()
        $Check.Disposed = $true
    }
}

function Get-UpdateFileSHA256 {
    param([Parameter(Mandatory = $true)][string]$Path)
    $hasher = [Security.Cryptography.SHA256]::Create()
    try {
        $stream = [IO.File]::OpenRead($Path)
        try { return [BitConverter]::ToString($hasher.ComputeHash($stream)).Replace('-', '').ToLowerInvariant() }
        finally { $stream.Dispose() }
    }
    finally { $hasher.Dispose() }
}

function Test-UpdateAssetHash {
    param([string]$Path, [string]$ExpectedSHA256)
    $expected = $ExpectedSHA256 -replace '^sha256:', ''
    if ($expected -notmatch '^[a-fA-F0-9]{64}$') { throw 'No valid SHA-256 checksum is available for the release asset.' }
    if ((Get-UpdateFileSHA256 -Path $Path) -cne $expected.ToLowerInvariant()) { throw 'The downloaded update did not match its published SHA-256 checksum.' }
    return $true
}

function ConvertTo-WindowsArgumentString {
    param([AllowEmptyCollection()][AllowNull()][string[]]$Arguments)
    $parts = foreach ($argument in $Arguments) {
        $builder = New-Object Text.StringBuilder
        $null = $builder.Append('"')
        $slashes = 0
        foreach ($character in ([string]$argument).ToCharArray()) {
            if ($character -eq [char]92) { $slashes++; continue }
            if ($character -eq [char]34) {
                $null = $builder.Append([char]92, (2 * $slashes + 1)).Append([char]34)
            }
            else {
                if ($slashes) { $null = $builder.Append([char]92, $slashes) }
                $null = $builder.Append($character)
            }
            $slashes = 0
        }
        if ($slashes) { $null = $builder.Append([char]92, (2 * $slashes)) }
        $null = $builder.Append('"')
        $builder.ToString()
    }
    return ($parts -join ' ')
}

function Invoke-UpdateReplacement {
    param([Parameter(Mandatory = $true)]$Payload)
    $replacementMutex = New-Object Threading.Mutex($false, 'Local\qBitLauncher.Update')
    $hasReplacementLock = $false
    try {
        try { $hasReplacementLock = $replacementMutex.WaitOne(45000) }
        catch [Threading.AbandonedMutexException] { $hasReplacementLock = $true }
        if (-not $hasReplacementLock) { throw 'Another update did not finish before the replacement timeout.' }
        $target = [IO.Path]::GetFullPath([string]$Payload.TargetPath)
        $stage = [IO.Path]::GetFullPath([string]$Payload.StagedPath)
        $backup = [IO.Path]::GetFullPath([string]$Payload.BackupPath)
        $directory = [IO.Path]::GetDirectoryName($target)
        if ([IO.Path]::GetDirectoryName($stage) -ine $directory -or [IO.Path]::GetDirectoryName($backup) -ine $directory -or $stage -ieq $target -or $backup -ieq $target -or $backup -ieq $stage) {
            throw 'Update files must use distinct paths in the application directory.'
        }
        if (-not [IO.File]::Exists($target)) { throw 'The application to update no longer exists.' }
        $null = Test-UpdateAssetHash -Path $stage -ExpectedSHA256 ([string]$Payload.SHA256)
        $waitUntil = [DateTime]::UtcNow.AddSeconds(45)
        if ([int]$Payload.ParentProcessId -gt 0) {
            while ($true) {
                $running = $null
                try { $running = [Diagnostics.Process]::GetProcessById([int]$Payload.ParentProcessId) } catch { break }
                try {
                    if ($Payload.ParentStartTimeUtc -and $running.StartTime.ToUniversalTime().ToString('o') -ne [string]$Payload.ParentStartTimeUtc) { break }
                    if ($running.HasExited) { break }
                }
                finally { if ($running) { $running.Dispose() } }
                if ([DateTime]::UtcNow -gt $waitUntil) { throw 'The running application did not close before the update timeout.' }
                Start-Sleep -Milliseconds 150
            }
        }
        # Revalidate after waiting, and keep all replacement files on the same volume.
        $null = Test-UpdateAssetHash -Path $stage -ExpectedSHA256 ([string]$Payload.SHA256)
        [IO.File]::Replace($stage, $target, $backup, $true)
        try {
            if (-not $Payload.SkipRestart) {
                $info = New-Object Diagnostics.ProcessStartInfo
                $info.UseShellExecute = $false
                $info.WorkingDirectory = $directory
                $launchArguments = @($Payload.Arguments | ForEach-Object { [string]$_ })
                if ($Payload.IsCompiled) {
                    $info.FileName = $target
                    $info.Arguments = ConvertTo-WindowsArgumentString -Arguments $launchArguments
                }
                else {
                    $info.FileName = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
                    $info.CreateNoWindow = $true
                    $info.WindowStyle = [Diagnostics.ProcessWindowStyle]::Hidden
                    $info.Arguments = ConvertTo-WindowsArgumentString -Arguments (@('-NoProfile', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', $target) + $launchArguments)
                }
                $process = [Diagnostics.Process]::Start($info)
                if (-not $process) { throw 'The updated application could not be started.' }
                $process.Dispose()
            }
            return [pscustomobject]@{ Updated = $true; TargetPath = $target; BackupPath = $backup }
        }
        catch {
            $failedPath = $target + '.failed-update-' + [Guid]::NewGuid().ToString('N') + '.bak'
            [IO.File]::Replace($backup, $target, $failedPath, $true)
            throw "The updated application failed to start; the previous version was restored. $($_.Exception.Message)"
        }
    }
    finally {
        if ($hasReplacementLock) { try { $replacementMutex.ReleaseMutex() } catch { } }
        $replacementMutex.Dispose()
    }
}

function Get-UpdateHandoffSource {
    $builder = New-Object Text.StringBuilder
    $null = $builder.AppendLine('param([Parameter(Mandatory = $true)][string]$PayloadPath)')
    $null = $builder.AppendLine('$ErrorActionPreference = ''Stop''')
    foreach ($name in @('Get-UpdateFileSHA256', 'Test-UpdateAssetHash', 'ConvertTo-WindowsArgumentString', 'Invoke-UpdateReplacement')) {
        $definition = (Get-Command $name -CommandType Function -ErrorAction Stop).Definition
        $null = $builder.AppendLine(('function ' + $name + ' {')).AppendLine($definition).AppendLine('}')
    }
    $null = $builder.AppendLine(@'
try {
    $payload = [IO.File]::ReadAllText($PayloadPath, [Text.Encoding]::UTF8) | ConvertFrom-Json
    $result = Invoke-UpdateReplacement -Payload $payload
    [IO.File]::WriteAllText($PayloadPath + '.result.json', ($result | ConvertTo-Json -Depth 8), [Text.Encoding]::UTF8)
}
catch {
    [IO.File]::WriteAllText($PayloadPath + '.result.json', (@{ Updated = $false; Error = $_.Exception.Message } | ConvertTo-Json), [Text.Encoding]::UTF8)
    exit 1
}
'@)
    return $builder.ToString()
}

function New-UpdateHandoff {
    param([Parameter(Mandatory = $true)]$Payload, [Parameter(Mandatory = $true)][string]$Directory)
    [IO.Directory]::CreateDirectory($Directory) | Out-Null
    $id = [Guid]::NewGuid().ToString('N')
    $scriptPath = Join-Path $Directory ('handoff-' + $id + '.ps1')
    $payloadPath = Join-Path $Directory ('handoff-' + $id + '.json')
    [IO.File]::WriteAllText($scriptPath, (Get-UpdateHandoffSource), (New-Object Text.UTF8Encoding($true)))
    [IO.File]::WriteAllText($payloadPath, ($Payload | ConvertTo-Json -Depth 10), (New-Object Text.UTF8Encoding($true)))
    $command = '& ' + "'" + $scriptPath.Replace("'", "''") + "' -PayloadPath '" + $payloadPath.Replace("'", "''") + "'"
    return [pscustomobject]@{ ScriptPath = $scriptPath; PayloadPath = $payloadPath; EncodedCommand = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($command)) }
}

function Get-UpdateExpectedSHA256 {
    param([Parameter(Mandatory = $true)]$Candidate)
    if ($Candidate.SHA256 -match '^[a-fA-F0-9]{64}$') { return $Candidate.SHA256.ToLowerInvariant() }
    if ($Candidate.ChecksumsUrl -notmatch '^https://github\.com/DeonHolo/qBitLauncher/releases/download/') { throw 'This release has no published SHA-256 checksum. Download it manually or wait for a verified release.' }
    $response = Invoke-WebRequest -Uri $Candidate.ChecksumsUrl -UseBasicParsing -Headers @{ 'User-Agent' = 'qBitLauncher' } -TimeoutSec 15 -ErrorAction Stop
    foreach ($line in ([string]$response.Content -split '\r?\n')) {
        if ($line -match '^([a-fA-F0-9]{64})\s+\*?(.+?)\s*$' -and $Matches[2] -ceq $Candidate.AssetName) { return $Matches[1].ToLowerInvariant() }
    }
    throw 'The release checksums do not include the requested application asset.'
}

function Update-Script {
    param([switch]$Restart)
    $updateMutex = $null
    $hasLock = $false
    $stagedPath = $null
    try {
        $updateMutex = New-Object Threading.Mutex($false, 'Local\qBitLauncher.Update')
        try { $hasLock = $updateMutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $hasLock = $true }
        if (-not $hasLock) { Write-LogMessage 'An update is already in progress.'; return $false }
        $candidate = $Global:AvailableUpdate
        if (-not $candidate) { $null = Get-RemoteVersion; $candidate = $Global:AvailableUpdate }
        if (-not $candidate -or [Version]$candidate.Version -le [Version]$Global:ScriptVersion) { return $false }
        $expected = Get-UpdateExpectedSHA256 -Candidate $candidate
        $targetPath = [IO.Path]::GetFullPath($Global:ExecutablePath)
        $stagedPath = Join-Path ([IO.Path]::GetDirectoryName($targetPath)) ('qBitLauncher.update-' + [Guid]::NewGuid().ToString('N') + [IO.Path]::GetExtension($targetPath))
        Write-LogMessage "Downloading verified release $($candidate.Tag)..."
        Invoke-WebRequest -Uri $candidate.DownloadUrl -OutFile $stagedPath -Headers @{ 'User-Agent' = 'qBitLauncher' } -UseBasicParsing -TimeoutSec 60 -ErrorAction Stop | Out-Null
        $null = Test-UpdateAssetHash -Path $stagedPath -ExpectedSHA256 $expected
        if (-not $Global:IsCompiledExe) {
            $tokens = $null; $errors = $null
            $null = [Management.Automation.Language.Parser]::ParseFile($stagedPath, [ref]$tokens, [ref]$errors)
            if ($errors.Count) { throw 'The verified source update could not be parsed.' }
        }
        $arguments = @()
        # Preserve positional empty values when later arguments are present.
        if ($filePathFromQB -or $torrentHashFromQB -or $torrentNameFromQB) { $arguments = @([string]$filePathFromQB, [string]$torrentHashFromQB, [string]$torrentNameFromQB) }
        $current = [Diagnostics.Process]::GetCurrentProcess()
        $payload = @{
            TargetPath = $targetPath; StagedPath = $stagedPath; BackupPath = $targetPath + '.previous.bak'
            SHA256 = $expected; ParentProcessId = $PID; ParentStartTimeUtc = $current.StartTime.ToUniversalTime().ToString('o')
            IsCompiled = [bool]$Global:IsCompiledExe; Arguments = $arguments; SkipRestart = (-not $Restart)
        }
        $current.Dispose()
        if (-not $Global:IsCompiledExe -and -not $Restart) {
            $payload.ParentProcessId = 0
            $null = Invoke-UpdateReplacement -Payload $payload
            $Global:ScriptVersion = $candidate.Version
            Write-LogMessage 'Source updated and previous version retained; reopen to load the new code.'
            return $true
        }
        $handoff = New-UpdateHandoff -Payload $payload -Directory (Join-Path (Get-AppDataDirectory) 'updates')
        $info = New-Object Diagnostics.ProcessStartInfo
        $info.FileName = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $info.Arguments = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -EncodedCommand ' + $handoff.EncodedCommand
        $info.UseShellExecute = $false
        $info.CreateNoWindow = $true
        $info.WindowStyle = [Diagnostics.ProcessWindowStyle]::Hidden
        $helper = [Diagnostics.Process]::Start($info)
        if (-not $helper) { throw 'The update handoff could not be started.' }
        $helper.Dispose()
        Write-LogMessage "Update handoff started; status will be saved to $($handoff.PayloadPath).result.json"
        [Environment]::Exit(0)
    }
    catch {
        Write-LogMessage "Update failed: $($_.Exception.Message)"
        if ($stagedPath -and [IO.File]::Exists($stagedPath)) { try { [IO.File]::Delete($stagedPath) } catch { } }
        if (Get-Command Show-ThemedMessageBox -ErrorAction SilentlyContinue) {
            $null = Show-ThemedMessageBox -Message "The current application has been kept.`n$($_.Exception.Message)" -Title 'Update Failed' -Icon 'Warning'
        }
        return $false
    }
    finally {
        if ($hasLock -and $updateMutex) { try { $updateMutex.ReleaseMutex() } catch { } }
        if ($updateMutex) { $updateMutex.Dispose() }
    }
}

# ---- Bundled from Source/Workflow.ps1 ----
# Pure workflow operations. Bundled into the standalone script by Build.ps1.
function Get-CanonicalPath {
    param([Parameter(Mandatory = $true)][string]$Path)
    $full = [IO.Path]::GetFullPath($Path)
    if (-not ('QBitLauncher.NativePaths' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.Text;
using Microsoft.Win32.SafeHandles;
namespace QBitLauncher {
    public static class NativePaths {
        [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
        static extern SafeFileHandle CreateFile(string path, uint access, uint share, IntPtr security, uint mode, uint flags, IntPtr template);
        [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
        static extern uint GetFinalPathNameByHandle(SafeFileHandle handle, StringBuilder path, uint length, uint flags);
        public static string Resolve(string path) {
            using (SafeFileHandle handle = CreateFile(path, 0, 7, IntPtr.Zero, 3, 0x02000000, IntPtr.Zero)) {
                if (handle.IsInvalid) throw new Win32Exception(Marshal.GetLastWin32Error());
                StringBuilder value = new StringBuilder(32768);
                uint length = GetFinalPathNameByHandle(handle, value, (uint)value.Capacity, 0);
                if (length == 0 || length >= value.Capacity) throw new Win32Exception(Marshal.GetLastWin32Error());
                string result = value.ToString();
                if (result.StartsWith(@"\\?\UNC\")) return @"\\" + result.Substring(8);
                if (result.StartsWith(@"\\?\")) return result.Substring(4);
                return result;
            }
        }
    }
}
'@ -ErrorAction Stop
    }
    if ([IO.File]::Exists($full) -or [IO.Directory]::Exists($full)) {
        $full = [QBitLauncher.NativePaths]::Resolve($full)
    }
    $root = [IO.Path]::GetPathRoot($full)
    if ($full.Length -gt $root.Length) { return $full.TrimEnd([char]92, [char]47) }
    return $root
}

function Test-PathContains {
    param([string]$Parent, [string]$Child)
    if ([string]::IsNullOrWhiteSpace($Parent) -or [string]::IsNullOrWhiteSpace($Child)) { return $false }
    $parentPath = Get-CanonicalPath $Parent
    $childPath = Get-CanonicalPath $Child
    return $childPath.Equals($parentPath, [StringComparison]::OrdinalIgnoreCase) -or
        $childPath.StartsWith($parentPath.TrimEnd([char]92) + '\', [StringComparison]::OrdinalIgnoreCase)
}

function Test-CleanupRoot {
    param([string]$Path)
    $canonical = Get-CanonicalPath $Path
    if ($canonical -eq [IO.Path]::GetPathRoot($canonical)) { throw 'A drive root cannot be a cleanup target.' }
    foreach ($protected in @($env:WINDIR, $env:USERPROFILE, $env:ProgramFiles, ${env:ProgramFiles(x86)}, $Global:ScriptDir)) {
        if ($protected -and (Test-PathContains -Parent $canonical -Child $protected)) {
            throw "This folder contains a protected application or Windows location: $Path"
        }
    }
    return $canonical
}

function Test-TreeHasReparsePoint {
    param([string]$Path)
    $pending = New-Object 'System.Collections.Generic.Stack[System.IO.DirectoryInfo]'
    $pending.Push((New-Object IO.DirectoryInfo($Path)))
    while ($pending.Count) {
        foreach ($entry in $pending.Pop().GetFileSystemInfos()) {
            if (($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { return $true }
            if ($entry -is [IO.DirectoryInfo]) { $pending.Push($entry) }
        }
    }
    return $false
}

function Get-CleanupPlan {
    param(
        [string]$SourcePath, [string]$ExtractedPath, [string]$SelectedPath,
        [ValidateSet('SourceOnly', 'ExtractedOnly', 'Everything')][string]$Mode = 'SourceOnly'
    )
    $roots = New-Object 'System.Collections.Generic.List[string]'
    if ($Mode -in @('SourceOnly', 'Everything') -and $SourcePath -and (Test-Path -LiteralPath $SourcePath)) { $roots.Add([IO.Path]::GetFullPath($SourcePath)) }
    if ($Mode -in @('ExtractedOnly', 'Everything') -and $ExtractedPath -and (Test-Path -LiteralPath $ExtractedPath)) { $roots.Add([IO.Path]::GetFullPath($ExtractedPath)) }
    foreach ($root in $roots) { [void](Test-CleanupRoot $root) }
    $protected = @()
    if ($Mode -eq 'SourceOnly') { $protected = @($ExtractedPath, $SelectedPath) | Where-Object { $_ -and (Test-Path -LiteralPath $_) } }
    $targets = New-Object 'System.Collections.Generic.List[object]'
    $retained = New-Object 'System.Collections.Generic.List[string]'
    $pending = New-Object 'System.Collections.Generic.Stack[string]'
    foreach ($root in $roots) { $pending.Push($root) }
    while ($pending.Count) {
        $path = $pending.Pop()
        $item = Get-Item -LiteralPath $path -Force -ErrorAction Stop
        if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
            $retained.Add($path)
            continue
        }
        $isProtected = $false; $containsProtected = $false
        foreach ($keep in $protected) {
            if (Test-PathContains -Parent $keep -Child $path) { $isProtected = $true; break }
            if (Test-PathContains -Parent $path -Child $keep) { $containsProtected = $true }
        }
        if ($isProtected) { $retained.Add($path); continue }
        if ($containsProtected -and $item.PSIsContainer) {
            foreach ($child in (Get-ChildItem -LiteralPath $path -Force -ErrorAction Stop)) { $pending.Push($child.FullName) }
            continue
        }
        # Never recycle a directory containing a junction: enumerate down to safe
        # children so deletion cannot follow a link outside the approved tree.
        if ($item.PSIsContainer) {
            $hasLinks = Test-TreeHasReparsePoint $path
            if ($hasLinks) {
                foreach ($child in (Get-ChildItem -LiteralPath $path -Force -ErrorAction Stop)) { $pending.Push($child.FullName) }
                continue
            }
        }
        $canonical = Get-CanonicalPath $path
        if (@($targets | Where-Object { $_.CanonicalPath -eq $canonical }).Count -eq 0) {
            $targets.Add([pscustomobject]@{ Path = $path; CanonicalPath = $canonical; IsDirectory = [bool]$item.PSIsContainer })
        }
    }
    $pruned = @($targets | Where-Object {
        $candidate = $_
        @($targets | Where-Object { $_.CanonicalPath -ne $candidate.CanonicalPath -and (Test-PathContains -Parent $_.CanonicalPath -Child $candidate.CanonicalPath) }).Count -eq 0
    })
    $affectsSelected = $false
    foreach ($target in $pruned) {
        if (($SelectedPath -and (Test-PathContains $target.Path $SelectedPath)) -or
            ($ExtractedPath -and (Test-PathContains $target.Path $ExtractedPath))) { $affectsSelected = $true }
    }
    return [pscustomobject]@{ Mode = $Mode; Targets = $pruned; Retained = $retained.ToArray(); ApprovedRoots = $roots.ToArray(); RequiresAcknowledgement = $affectsSelected; SourcePath = $SourcePath; ExtractedPath = $ExtractedPath; SelectedPath = $SelectedPath }
}

function Invoke-CleanupPlan {
    param($Plan, [switch]$AcknowledgeSelectedFiles, [switch]$PermanentlyDelete)
    if ($Plan.RequiresAcknowledgement -and -not $AcknowledgeSelectedFiles) { throw 'Explicit confirmation is required to delete the extracted app or selected file.' }
    Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction Stop
    $deleted = New-Object 'System.Collections.Generic.List[string]'
    foreach ($target in $Plan.Targets) {
        if (-not (Test-Path -LiteralPath $target.Path)) { continue }
        [void](Test-CleanupRoot $target.Path)
        $current = Get-CanonicalPath $target.Path
        if ($current -ne $target.CanonicalPath) { throw "Cleanup path changed after preview: $($target.Path)" }
        if (@($Plan.ApprovedRoots | Where-Object { Test-PathContains $_ $target.Path }).Count -eq 0) { throw 'Cleanup target is outside the approved locations.' }
        $item = Get-Item -LiteralPath $target.Path -Force -ErrorAction Stop
        if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Cleanup will not follow a junction or symbolic link.' }
        if ($item.PSIsContainer -and (Test-TreeHasReparsePoint $target.Path)) { throw 'The folder now contains a junction or symbolic link. Prepare a new cleanup preview.' }
        if ($Plan.Mode -eq 'SourceOnly') {
            foreach ($keep in @($Plan.ExtractedPath, $Plan.SelectedPath)) {
                if ($keep -and ((Test-PathContains $target.Path $keep) -or (Test-PathContains $keep $target.Path))) { throw 'This action would remove files marked to keep.' }
            }
        }
        $recycle = [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin
        if ($PermanentlyDelete) { $recycle = [Microsoft.VisualBasic.FileIO.RecycleOption]::DeletePermanently }
        if ($item.PSIsContainer) {
            [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory($target.Path, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, $recycle, [Microsoft.VisualBasic.FileIO.UICancelOption]::ThrowException)
        } else {
            [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($target.Path, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, $recycle, [Microsoft.VisualBasic.FileIO.UICancelOption]::ThrowException)
        }
        $deleted.Add($target.Path)
    }
    return [pscustomobject]@{ Deleted = $deleted.ToArray(); Recycled = -not $PermanentlyDelete }
}

function ConvertTo-ShortcutLabel {
    param([string]$Label)
    $name = $Label.Trim()
    if ($name.EndsWith('.lnk', [StringComparison]::OrdinalIgnoreCase)) { $name = $name.Substring(0, $name.Length - 4) }
    if ([string]::IsNullOrWhiteSpace($name) -or $name.IndexOfAny([IO.Path]::GetInvalidFileNameChars()) -ge 0 -or $name -match '[ .]$' -or
        $name -match '^(?i:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)') { throw 'Enter a valid shortcut name without reserved Windows names, trailing dots, or path characters.' }
    if ($name.Length -gt 180) { throw 'Please keep the shortcut name under 181 characters.' }
    return $name
}

function Get-AvailableShortcutPath {
    param([string]$Directory, [string]$Label)
    $name = ConvertTo-ShortcutLabel $Label
    $path = Join-Path $Directory ($name + '.lnk')
    $number = 2
    while (Test-Path -LiteralPath $path) { $path = Join-Path $Directory ("$name ($number).lnk"); $number++ }
    return $path
}

function Get-RunnableRank {
    param([IO.FileInfo]$File, [string]$RootFolder)
    $path = $File.FullName; $name = $File.BaseName
    $depth = ($path.Substring([Math]::Min($RootFolder.Length, $path.Length)).Split([char]92).Count)
    $helper = $name -match '(?i)^(?:unins\d*|uninstall.*|unitycrashhandler.*|crashpad_handler|crashreport(?:client|er).*|crashhandler.*|vcredist.*|dxsetup|cefsubprocess|redist.*|diagnostic.*|benchmark)$'
    $score = 100 - [Math]::Min(60, $depth * 5)
    $reason = 'Application'
    if ($name -match '^(?i:setup|install)(?:[._ -]|$)') { $score += 25; $reason = 'Installer' }
    if ($helper -or $path -match '(?i)[\\/](?:_CommonRedist|redist|prerequisites)[\\/]') { $score -= 150; $helper = $true; $reason = 'Helper / maintenance' }
    if ($File.Extension -in @('.bat', '.cmd')) { $score -= 5; if (-not $helper) { $reason = 'Launch script' } }
    return [pscustomobject]@{ Score = $score; Helper = $helper; Reason = $reason }
}

function New-RunnableStartInfo {
    param([string]$Path, [string]$Arguments = '', [bool]$AsAdmin = $true)
    $file = Get-Item -LiteralPath $Path -ErrorAction Stop
    if ($file.PSIsContainer -or $file.Extension -notin @('.exe', '.bat', '.cmd')) { throw 'Choose an EXE, BAT, or CMD file.' }
    $info = New-Object Diagnostics.ProcessStartInfo
    $info.UseShellExecute = $true
    $info.WorkingDirectory = $file.DirectoryName
    if ($AsAdmin) { $info.Verb = 'runas' }
    if ($file.Extension -eq '.exe') {
        $info.FileName = $file.FullName; $info.Arguments = $Arguments
    } else {
        # Elevate a Unicode PowerShell handoff, then pass the script path through
        # one environment expansion in cmd. Literal %VAR% in filenames survives.
        $payload = @{ Path = $file.FullName; Directory = $file.DirectoryName; Arguments = $Arguments } | ConvertTo-Json -Compress
        $encodedPayload = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($payload))
        $command = @'
$payload = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('PAYLOAD')) | ConvertFrom-Json
$info = New-Object Diagnostics.ProcessStartInfo
$info.UseShellExecute = $false
$info.FileName = Join-Path $env:WINDIR 'System32\cmd.exe'
$info.WorkingDirectory = $payload.Directory
$info.EnvironmentVariables['QBITLAUNCHER_SCRIPT_TARGET'] = $payload.Path
$info.Arguments = '/d /v:off /s /c ""%QBITLAUNCHER_SCRIPT_TARGET%" ' + $payload.Arguments + '"'
$process = [Diagnostics.Process]::Start($info)
$process.WaitForExit()
$exitCode = $process.ExitCode
$process.Dispose()
exit $exitCode
'@
        $command = $command.Replace('PAYLOAD', $encodedPayload)
        $info.FileName = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $info.Arguments = '-NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -EncodedCommand ' + [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($command))
        $info.WindowStyle = [Diagnostics.ProcessWindowStyle]::Hidden
    }
    return $info
}

function Start-Runnable {
    param([string]$Path, [string]$Arguments = '', [bool]$AsAdmin = $true)
    $info = New-RunnableStartInfo -Path $Path -Arguments $Arguments -AsAdmin $AsAdmin
    $process = [Diagnostics.Process]::Start($info)
    if ($process) { $process.Dispose() }
}

function Initialize-FolderScanner {
    if ('QBitLauncher.FolderScan' -as [type]) { return }
    Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Security;
using System.Threading;
using System.Threading.Tasks;
using System.Text;
using System.Text.RegularExpressions;
namespace QBitLauncher {
    public sealed class ArchiveOutputFile {
        public string Path;
        public long Length;
        public ArchiveOutputFile(string path,long length) { Path=path; Length=length; }
    }
    public sealed class ArchiveOutputCheck {
        public bool Valid;
        public int Checked;
        public string[] Problems;
        public string DestinationPath;
    }
    public sealed class FolderScanProgress {
        public readonly long Files;
        public readonly int Folders, PendingFolders, Runnables, Skipped;
        public readonly string CurrentPath;
        public readonly string Phase;
        public readonly bool Complete;
        public FolderScanProgress(long files, int folders, int pending, int runnables, int skipped, string path, bool complete, string phase="Scanning files") {
            Files=files; Folders=folders; PendingFolders=pending; Runnables=runnables; Skipped=skipped; CurrentPath=path; Complete=complete;
            Phase=phase;
        }
    }
    public sealed class FolderScanResult {
        public string RootFolder;
        public FileInfo[] Runnables, AllArchives, Media;
        public string[] Skipped;
        public bool Complete;
        public ArchiveOutputCheck OutputCheck;
    }
    public sealed class FolderScan : IDisposable {
        readonly string root;
        readonly string archivePath, listTool;
        readonly CancellationTokenSource cancellation = new CancellationTokenSource();
        readonly object gate = new object();
        readonly List<FileInfo> runnables = new List<FileInfo>(), archives = new List<FileInfo>(), media = new List<FileInfo>();
        readonly List<string> skipped = new List<string>();
        FolderScanProgress progress;
        int disposed;
        ArchiveOutputCheck outputCheck;
        public Task<FolderScanResult> Operation { get; private set; }
        public FolderScanProgress Progress { get { return Volatile.Read(ref progress); } }
        public FolderScan(string path) : this(path,null,null) { }
        public FolderScan(string path,string archive,string tool) {
            root=Path.GetFullPath(path);
            archivePath=archive; listTool=tool;
            progress=new FolderScanProgress(0,0,1,0,0,root,false);
            Operation=Task.Factory.StartNew<FolderScanResult>(new Func<FolderScanResult>(Scan), cancellation.Token, TaskCreationOptions.None, TaskScheduler.Default);
        }
        public FolderScanResult Snapshot(bool complete) {
            lock(gate) { return new FolderScanResult { RootFolder=root, Runnables=runnables.ToArray(), AllArchives=archives.ToArray(), Media=media.ToArray(), Skipped=skipped.ToArray(), Complete=complete, OutputCheck=outputCheck }; }
        }
        public void Cancel() { if(Volatile.Read(ref disposed)==0) cancellation.Cancel(); }
        public void Dispose() {
            if(Interlocked.Exchange(ref disposed,1)!=0) return;
            cancellation.Cancel();
            // Never wait on disk I/O from the UI thread, including cancellation.
            Operation.ContinueWith(task => { if(task.IsFaulted) { var observed=task.Exception; } cancellation.Dispose(); }, TaskScheduler.Default);
        }
        FolderScanResult Scan() {
            CancellationToken token=cancellation.Token;
            DirectoryInfo start=new DirectoryInfo(root);
            if(!start.Exists) throw new DirectoryNotFoundException("The scan folder is missing or inaccessible: "+root);
            if((start.Attributes & FileAttributes.Directory)==0) throw new IOException("Choose a folder to scan: "+root);
            Queue<DirectoryInfo> pending=new Queue<DirectoryInfo>(); pending.Enqueue(start);
            long files=0; int folders=0;
            Stopwatch pulse=Stopwatch.StartNew();
            while(pending.Count>0) {
                token.ThrowIfCancellationRequested();
                DirectoryInfo directory=pending.Dequeue();
                Publish(files,folders,pending.Count+1,directory.FullName,false);
                try {
                    // Stream metadata only. Do not read payloads or allocate an
                    // array for every file in a large directory.
                    using(IEnumerator<FileSystemInfo> entries=directory.EnumerateFileSystemInfos().GetEnumerator()) {
                        while(true) {
                            token.ThrowIfCancellationRequested();
                            if(!entries.MoveNext()) break;
                            FileSystemInfo entry=entries.Current;
                            try {
                                if((entry.Attributes & FileAttributes.ReparsePoint)!=0) { lock(gate) skipped.Add(entry.FullName); continue; }
                                DirectoryInfo child=entry as DirectoryInfo;
                                if(child!=null) { pending.Enqueue(child); continue; }
                                files++;
                                FileInfo file=(FileInfo)entry;
                                string extension=file.Extension.ToLowerInvariant();
                                if(extension==".exe" || extension==".bat" || extension==".cmd") { lock(gate) runnables.Add(file); }
                                else if(extension==".zip" || extension==".rar" || extension==".7z" || extension==".iso" || extension==".img" || file.Name.EndsWith(".7z.001",StringComparison.OrdinalIgnoreCase) || file.Name.EndsWith(".zip.001",StringComparison.OrdinalIgnoreCase)) { lock(gate) archives.Add(file); }
                                else if(extension==".mp4" || extension==".mkv" || extension==".avi" || extension==".mov" || extension==".wmv" || extension==".flv" || extension==".mp3" || extension==".flac" || extension==".wav" || extension==".aac" || extension==".ogg" || extension==".webm" || extension==".m4a") { lock(gate) media.Add(file); }
                            } catch(UnauthorizedAccessException) { lock(gate) skipped.Add(entry.FullName); }
                              catch(IOException) { lock(gate) skipped.Add(entry.FullName); }
                              catch(SecurityException) { lock(gate) skipped.Add(entry.FullName); }
                            if(pulse.ElapsedMilliseconds>=150) { Publish(files,folders,pending.Count+1,directory.FullName,false); pulse.Restart(); }
                        }
                    }
                } catch(UnauthorizedAccessException) { lock(gate) skipped.Add(directory.FullName); }
                  catch(IOException) { lock(gate) skipped.Add(directory.FullName); }
                  catch(SecurityException) { lock(gate) skipped.Add(directory.FullName); }
                folders++;
            }
            token.ThrowIfCancellationRequested();
            if(!String.IsNullOrEmpty(archivePath) && !String.IsNullOrEmpty(listTool)) {
                Publish(files,folders,0,archivePath,false,"Checking archive file list");
                ArchiveOutputFile[] manifest=ReadArchiveManifest(archivePath,listTool,15000,token);
                if(manifest!=null) {
                    outputCheck=ValidateArchiveOutput(manifest,root,token,path=>Publish(files,folders,0,path,false,"Checking extracted file sizes"));
                }
            }
            Publish(files,folders,0,root,true);
            return Snapshot(true);
        }
        void Publish(long files,int folders,int pending,string path,bool complete,string phase="Scanning files") {
            lock(gate) { Volatile.Write(ref progress,new FolderScanProgress(files,folders,pending,runnables.Count,skipped.Count,path,complete,phase)); }
        }
        public static ArchiveOutputFile[] ReadArchiveManifest(string archive,string tool,int timeout,CancellationToken token) {
            if(String.IsNullOrEmpty(tool) || !File.Exists(tool)) return null;
            using(Process process=new Process()) {
                process.StartInfo=new ProcessStartInfo { FileName=tool, Arguments="l -slt -ba -sccUTF-8 -p- -- \""+archive+"\"", UseShellExecute=false, CreateNoWindow=true, RedirectStandardOutput=true, RedirectStandardError=true, StandardOutputEncoding=Encoding.UTF8 };
                bool started=false;
                try {
                    process.Start(); started=true;
                    Task<string> output=process.StandardOutput.ReadToEndAsync(), errors=process.StandardError.ReadToEndAsync();
                    Stopwatch watch=Stopwatch.StartNew();
                    while(!process.WaitForExit(Math.Min(100,Math.Max(1,timeout)))) {
                        token.ThrowIfCancellationRequested();
                        if(watch.ElapsedMilliseconds>=timeout) return null;
                    }
                    token.ThrowIfCancellationRequested();
                    if(process.ExitCode!=0) return null;
                    while(!output.IsCompleted || !errors.IsCompleted) {
                        token.ThrowIfCancellationRequested();
                        if(watch.ElapsedMilliseconds>=timeout) return null;
                        Thread.Sleep(10);
                    }
                    string text=output.GetAwaiter().GetResult(); errors.GetAwaiter().GetResult();
                    List<ArchiveOutputFile> entries=new List<ArchiveOutputFile>();
                    foreach(string block in Regex.Split(text,@"\r?\n\s*\r?\n")) {
                        token.ThrowIfCancellationRequested();
                        Match path=Regex.Match(block,@"(?m)^Path = (.+)\r?$"), length=Regex.Match(block,@"(?m)^Size = ([0-9]+)\r?$");
                        long bytes;
                        if(!path.Success || !length.Success || !Int64.TryParse(length.Groups[1].Value,out bytes) || Regex.IsMatch(block,@"(?m)^Folder = \+\r?$|^Attributes = D")) continue;
                        entries.Add(new ArchiveOutputFile(path.Groups[1].Value.TrimEnd('\r'),bytes));
                    }
                    return entries.Count==0 ? null : entries.ToArray();
                } catch(OperationCanceledException) { throw; }
                  catch(Exception) { return null; }
                finally { if(started) { try { if(!process.HasExited) { process.Kill(); process.WaitForExit(500); } } catch(InvalidOperationException) { } } }
            }
        }
        public static ArchiveOutputCheck ValidateArchiveOutput(ArchiveOutputFile[] manifest,string destination,CancellationToken token,Action<string> onProgress) {
            string root=Path.GetFullPath(destination).TrimEnd('\\','/')+Path.DirectorySeparatorChar;
            List<string> problems=new List<string>(); int count=0;
            Stopwatch pulse=Stopwatch.StartNew();
            foreach(ArchiveOutputFile entry in manifest) {
                token.ThrowIfCancellationRequested();
                string path=Path.GetFullPath(Path.Combine(root,entry.Path.Replace('/','\\')));
                if(Path.IsPathRooted(entry.Path) || !path.StartsWith(root,StringComparison.OrdinalIgnoreCase)) throw new IOException("The archive contains a path outside the extraction destination.");
                try {
                    FileInfo file=new FileInfo(path);
                    if(!file.Exists) problems.Add("Missing: "+entry.Path);
                    else if(file.Length!=entry.Length) problems.Add(String.Format("Incomplete: {0} ({1:N0} of {2:N0} bytes)",entry.Path,file.Length,entry.Length));
                } catch(IOException) { problems.Add("Cannot check: "+entry.Path); }
                  catch(UnauthorizedAccessException) { problems.Add("Cannot check: "+entry.Path); }
                  catch(SecurityException) { problems.Add("Cannot check: "+entry.Path); }
                count++;
                if(onProgress!=null && pulse.ElapsedMilliseconds>=150) { onProgress(path); pulse.Restart(); }
            }
            return new ArchiveOutputCheck { Valid=count>0 && problems.Count==0, Checked=count, Problems=problems.ToArray(), DestinationPath=destination };
        }
    }
}
'@ -ErrorAction Stop
}

function ConvertTo-FolderInventory {
    param($ScanResult)
    $root = $ScanResult.RootFolder
    $sorted = @($ScanResult.Runnables | Sort-Object @{ Expression = { (Get-RunnableRank $_ $root).Score }; Descending = $true }, FullName)
    $payloads = @($ScanResult.AllArchives | Where-Object {
        $_.FullName -notmatch '(?i)[\\/](?:plugins|_Data|resources|assets|redist|crack)[\\/]' -and
        $_.Name -notmatch '(?i)\.part0*[2-9][0-9]*\.rar$|\.part0*1[0-9]+\.rar$'
    } | Sort-Object @{ Expression = { $_.FullName.Split([char]92).Count } }, @{ Expression = { $_.Length }; Descending = $true })
    return [pscustomobject]@{ RootFolder = $root; Runnables = $sorted; Archives = $payloads; AllArchives = @($ScanResult.AllArchives); Media = @($ScanResult.Media); Skipped = @($ScanResult.Skipped); Complete = $ScanResult.Complete; OutputCheck = $ScanResult.OutputCheck }
}

function Start-FolderScan {
    param([string]$RootFolder, [string]$ArchivePath, [string]$ListToolPath)
    Initialize-FolderScanner
    return New-Object QBitLauncher.FolderScan($RootFolder, $ArchivePath, $ListToolPath)
}

function Get-FolderInventory {
    param([string]$RootFolder)
    $scan = Start-FolderScan $RootFolder
    try { return ConvertTo-FolderInventory ($scan.Operation.GetAwaiter().GetResult()) }
    finally { $scan.Dispose() }
}

function Get-PrimaryContent {
    param($Inventory)
    $root = $Inventory.RootFolder.TrimEnd([char]92)
    $shallow = @($Inventory.Archives | Where-Object { $_.DirectoryName.TrimEnd([char]92) -eq $root })
    $mainRunnables = @($Inventory.Runnables | Where-Object { -not (Get-RunnableRank $_ $root).Helper })
    if ($mainRunnables.Count -and -not $shallow.Count) { return [pscustomobject]@{ Kind = 'Runnables'; Files = @($Inventory.Runnables) } }
    $candidates = if ($shallow.Count) { $shallow } else { @($Inventory.Archives) }
    if ($candidates.Count) {
        $depth = ($candidates[0].DirectoryName.Split([char]92).Count)
        $candidates = @($candidates | Where-Object { $_.DirectoryName.Split([char]92).Count -eq $depth })
        return [pscustomobject]@{ Kind = 'Archives'; Files = $candidates }
    }
    if ($Inventory.Runnables.Count) { return [pscustomobject]@{ Kind = 'Runnables'; Files = @($Inventory.Runnables) } }
    return [pscustomobject]@{ Kind = 'Other'; Files = @($Inventory.Media) }
}

function Get-QBittorrentRepairLines {
    param([string[]]$Lines, [int]$Port = 8080)
    if ($Port -lt 1 -or $Port -gt 65535) { throw 'API port must be between 1 and 65535.' }
    $result = Set-QBittorrentIniValue -Lines $Lines -Key 'WebUI\Enabled' -Value 'true'
    $result = Set-QBittorrentIniValue -Lines $result -Key 'WebUI\Port' -Value ([string]$Port)
    $result = Set-QBittorrentIniValue -Lines $result -Key 'WebUI\Address' -Value '127.0.0.1'
    # Preserve every authentication, password, HTTPS, and host-validation setting.
    return ,$result
}

function Enable-QBittorrentLocalApiConfig {
    param([int]$Port = 8080)
    $state = Get-QBittorrentWebApiState
    if (-not $state.Exists) { throw 'qBittorrent.ini was not found. Start qBittorrent once before setting up cleanup.' }
    if (Test-QBittorrentProcessRunning) { throw 'Close qBittorrent before applying its configuration changes.' }
    $lines = [IO.File]::ReadAllLines($state.ConfigPath)
    $updated = Get-QBittorrentRepairLines -Lines $lines -Port $Port
    $backup = $state.ConfigPath + '.qBitLauncher-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [Guid]::NewGuid().ToString('N').Substring(0, 8) + '.bak'
    [IO.File]::Copy($state.ConfigPath, $backup)
    $temporary = $state.ConfigPath + '.' + [Guid]::NewGuid().ToString('N') + '.tmp'
    try {
        [IO.File]::WriteAllLines($temporary, [string[]]$updated, (New-Object Text.UTF8Encoding($false)))
        [IO.File]::Replace($temporary, $state.ConfigPath, [NullString]::Value)
    } finally { if ([IO.File]::Exists($temporary)) { [IO.File]::Delete($temporary) } }
    Write-LogMessage 'Enabled the qBittorrent loopback API while preserving existing authentication settings.'
    return $backup
}

function Get-RunnableIconBytes {
    param([IO.FileInfo]$File, [string]$CacheDirectory)
    try {
        $hash = [Security.Cryptography.SHA256]::Create()
        try { $key = [BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes($File.FullName + '|' + $File.LastWriteTimeUtc.Ticks + '|' + $File.Length))).Replace('-', '') } finally { $hash.Dispose() }
        [IO.Directory]::CreateDirectory($CacheDirectory) | Out-Null
        $cachePath = Join-Path $CacheDirectory ($key + '.png')
        if ([IO.File]::Exists($cachePath)) { return ,([IO.File]::ReadAllBytes($cachePath)) }
        $icon = [Drawing.Icon]::ExtractAssociatedIcon($File.FullName)
        if (-not $icon) { return $null }
        try {
            $bitmap = $icon.ToBitmap(); $stream = New-Object IO.MemoryStream
            try { $bitmap.Save($stream, [Drawing.Imaging.ImageFormat]::Png); $bytes = $stream.ToArray(); [IO.File]::WriteAllBytes($cachePath, $bytes); return ,$bytes }
            finally { $stream.Dispose(); $bitmap.Dispose() }
        } finally { $icon.Dispose() }
    } catch { return $null }
}

function New-WindowsShortcut {
    param(
        [Parameter(Mandatory = $true)]
        [string]$ShortcutPath,
        [Parameter(Mandatory = $true)]
        [string]$TargetPath,
        [string]$WorkingDirectory,
        [string]$Arguments = ""
    )

    $target = Get-Item -LiteralPath $TargetPath -ErrorAction Stop
    if ($target.PSIsContainer) {
        throw "The shortcut target must be a file: $TargetPath"
    }
    if ([string]::IsNullOrWhiteSpace($WorkingDirectory)) {
        $WorkingDirectory = $target.DirectoryName
    }
    if (-not (Test-Path -LiteralPath $WorkingDirectory -PathType Container)) {
        throw "The shortcut working directory does not exist: $WorkingDirectory"
    }

    if (-not ('QBitLauncher.ShortcutWriter' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.ComTypes;
using System.Text;

namespace QBitLauncher
{
    public static class ShortcutWriter
    {
        [ComImport, Guid("00021401-0000-0000-C000-000000000046")]
        private class ShellLink { }

        // Keep the complete native vtable order, including unused members.
        [ComImport, Guid("000214F9-0000-0000-C000-000000000046")]
        [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        private interface IShellLinkW
        {
            void GetPath([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder path, int length, IntPtr findData, uint flags);
            void GetIDList(out IntPtr itemList);
            void SetIDList(IntPtr itemList);
            void GetDescription([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder description, int length);
            void SetDescription([MarshalAs(UnmanagedType.LPWStr)] string description);
            void GetWorkingDirectory([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder directory, int length);
            void SetWorkingDirectory([MarshalAs(UnmanagedType.LPWStr)] string directory);
            void GetArguments([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder arguments, int length);
            void SetArguments([MarshalAs(UnmanagedType.LPWStr)] string arguments);
            void GetHotkey(out short hotkey);
            void SetHotkey(short hotkey);
            void GetShowCmd(out int showCommand);
            void SetShowCmd(int showCommand);
            void GetIconLocation([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder path, int length, out int index);
            void SetIconLocation([MarshalAs(UnmanagedType.LPWStr)] string path, int index);
            void SetRelativePath([MarshalAs(UnmanagedType.LPWStr)] string path, uint reserved);
            void Resolve(IntPtr window, uint flags);
            void SetPath([MarshalAs(UnmanagedType.LPWStr)] string path);
        }

        public static void Save(string shortcutPath, string targetPath, string workingDirectory, string arguments)
        {
            object shellLink = new ShellLink();
            try
            {
                IShellLinkW link = (IShellLinkW)shellLink;
                link.SetPath(targetPath);
                link.SetWorkingDirectory(workingDirectory);
                link.SetArguments(arguments ?? String.Empty);
                ((IPersistFile)shellLink).Save(shortcutPath, true);
            }
            finally
            {
                Marshal.FinalReleaseComObject(shellLink);
            }
        }
    }
}
'@ -ErrorAction Stop
    }

    [QBitLauncher.ShortcutWriter]::Save([IO.Path]::GetFullPath($ShortcutPath), $target.FullName, $WorkingDirectory, $Arguments)
}

# ---- Bundled from Source/Extraction.ps1 ----
# Synchronous entry points for metadata verification. The scan UI uses the same
# native operations in its cancellable task, without blocking the UI thread.
function Get-ArchiveOutputManifest {
    param([string]$ArchivePath, [string]$ListToolPath, [int]$TimeoutMilliseconds = 15000)
    Initialize-FolderScanner
    $entries = [QBitLauncher.FolderScan]::ReadArchiveManifest($ArchivePath, $ListToolPath, $TimeoutMilliseconds, [Threading.CancellationToken]::None)
    if ($null -eq $entries) { return $null }
    return ,$entries
}

function Test-ArchiveOutput {
    param([object[]]$Manifest, [string]$DestinationPath)
    Initialize-FolderScanner
    $entries = New-Object 'System.Collections.Generic.List[QBitLauncher.ArchiveOutputFile]'
    foreach ($entry in $Manifest) { $entries.Add((New-Object QBitLauncher.ArchiveOutputFile([string]$entry.Path, [long]$entry.Length))) }
    return [QBitLauncher.FolderScan]::ValidateArchiveOutput($entries.ToArray(), $DestinationPath, [Threading.CancellationToken]::None, $null)
}

# ---- Bundled from Source/UI.ps1 ----
# Windows Forms presentation. Worker runspaces never access controls.
function Initialize-AppPresentation {
    if ('QBitLauncher.Presentation' -as [type]) { return }
    Add-Type -ReferencedAssemblies System.Windows.Forms, System.Drawing -TypeDefinition @'
using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace QBitLauncher {
    public static class Presentation {
        [DllImport("dwmapi.dll")] static extern int DwmSetWindowAttribute(IntPtr window, int attribute, ref int value, int size);
        [DllImport("uxtheme.dll", CharSet=CharSet.Unicode)] public static extern int SetWindowTheme(IntPtr window, string application, string list);
        [DllImport("user32.dll")] static extern bool PrintWindow(IntPtr window, IntPtr device, uint flags);
        public static void Capture(Form form, string path) {
            using (Bitmap bitmap = new Bitmap(form.Width,form.Height)) {
                using (Graphics graphics = Graphics.FromImage(bitmap)) {
                    IntPtr device = graphics.GetHdc();
                    try { if (!PrintWindow(form.Handle,device,0)) throw new InvalidOperationException("The window could not be captured."); }
                    finally { graphics.ReleaseHdc(device); }
                }
                bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);
            }
        }
        public static void TitleBar(Form form, bool dark, Color caption, Color text) {
            try {
                int enabled = dark ? 1 : 0;
                DwmSetWindowAttribute(form.Handle, 20, ref enabled, 4);
                int background = caption.R | (caption.G << 8) | (caption.B << 16);
                int foreground = text.R | (text.G << 8) | (text.B << 16);
                DwmSetWindowAttribute(form.Handle, 35, ref background, 4);
                DwmSetWindowAttribute(form.Handle, 36, ref foreground, 4);
            } catch (DllNotFoundException) { } catch (EntryPointNotFoundException) { }
        }
    }
    public class ThemedListView : ListView {
        public Color HeaderColor { get; set; }
        public Color MutedColor { get; set; }
        public Color SelectionColor { get; set; }
        public Color AccentColor { get; set; }
        public Color DividerColor { get; set; }
        public bool Dark { get; set; }
        bool fitting;
        int[] preferred;
        HeaderWindow header;
        ListViewItem editingItem;
        Panel editorSurface;
        TextBox nameEditor;
        public bool IsShortcutNameEditing { get { return editingItem != null; } }
        [StructLayout(LayoutKind.Sequential)] struct NativeRect { public int Left, Top, Right, Bottom; }
        [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr window, int message, IntPtr first, IntPtr second);
        [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr window, int message, IntPtr first, ref NativeRect rectangle);
        [DllImport("user32.dll")] static extern bool GetClientRect(IntPtr window, out NativeRect rectangle);
        [DllImport("user32.dll")] static extern IntPtr GetDC(IntPtr window);
        [DllImport("user32.dll")] static extern int ReleaseDC(IntPtr window, IntPtr device);
        [DllImport("user32.dll")] static extern int GetScrollPos(IntPtr window, int bar);
        [DllImport("user32.dll")] static extern bool InvalidateRect(IntPtr window, IntPtr rectangle, bool erase);
        sealed class HeaderWindow : NativeWindow {
            readonly ThemedListView owner;
            public HeaderWindow(ThemedListView list, IntPtr handle) { owner = list; AssignHandle(handle); }
            protected override void WndProc(ref Message message) {
                base.WndProc(ref message);
                if (message.Msg != 0x000F && message.Msg != 0x0318) return;
                IntPtr device = message.Msg == 0x0318 ? message.WParam : GetDC(Handle);
                try { if (device != IntPtr.Zero) owner.PaintHeader(Handle, device); }
                finally { if (message.Msg == 0x000F && device != IntPtr.Zero) ReleaseDC(Handle, device); }
            }
        }
        public ThemedListView() {
            OwnerDraw = true; DoubleBuffered = true; BorderStyle = BorderStyle.None;
            HeaderColor = Color.FromArgb(40,42,54); MutedColor = Color.FromArgb(150,150,150);
            SelectionColor = Color.FromArgb(68,71,90); AccentColor = Color.FromArgb(98,114,164);
            DividerColor = Color.FromArgb(68,71,90); Dark = true;
        }
        protected override void OnHandleCreated(EventArgs e) {
            base.OnHandleCreated(e);
            Presentation.SetWindowTheme(Handle, Dark ? "DarkMode_Explorer" : "Explorer", null);
            IntPtr handle = SendMessage(Handle, 0x101F, IntPtr.Zero, IntPtr.Zero);
            if (handle != IntPtr.Zero) header = new HeaderWindow(this, handle);
        }
        protected override void OnHandleDestroyed(EventArgs e) {
            FinishShortcutNameEdit(true);
            if (header != null) { header.ReleaseHandle(); header = null; }
            base.OnHandleDestroyed(e);
        }
        void PaintHeader(IntPtr handle, IntPtr device) {
            NativeRect client;
            if (!GetClientRect(handle, out client)) return;
            using (Graphics graphics = Graphics.FromHdc(device))
            using (Brush surface = new SolidBrush(HeaderColor))
            using (Pen divider = new Pen(DividerColor)) {
                // Paint the entire native header, including its empty trailing area.
                graphics.FillRectangle(surface, 0, 0, client.Right, client.Bottom);
                for (int index = 0; index < Columns.Count; index++) {
                    NativeRect native = new NativeRect();
                    SendMessage(handle, 0x1207, new IntPtr(index), ref native);
                    Rectangle text = new Rectangle(native.Left+10,native.Top,Math.Max(0,native.Right-native.Left-18),native.Bottom-native.Top);
                    TextRenderer.DrawText(graphics, Columns[index].Text, Font, text, MutedColor, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
                    graphics.DrawLine(divider,native.Right-1,native.Top+4,native.Right-1,native.Bottom-5);
                }
                graphics.DrawLine(divider,0,client.Bottom-1,client.Right,client.Bottom-1);
            }
        }
        public void RefreshHeader() {
            if (header != null) InvalidateRect(header.Handle, IntPtr.Zero, false);
        }
        public void FitColumns() {
            if (fitting || Columns.Count != 4 || ClientSize.Width < 80) return;
            fitting = true;
            try {
                int width = Math.Max(60, ClientSize.Width-1);
                if (preferred == null) preferred = new int[]{(int)(width*.30),(int)(width*.27),(int)(width*.17)};
                // Recover collapsed/invalid saved columns instead of hiding their labels.
                int first = Math.Max(100,preferred[0]), second = Math.Max(100,preferred[1]), third = Math.Max(78,preferred[2]);
                int used = Math.Max(1, first+second+third);
                if (used > width-60) {
                    double scale = Math.Max(1,width-60)/(double)used;
                    first = (int)(first*scale); second = (int)(second*scale); third = (int)(third*scale);
                }
                Columns[0].Width = first; Columns[1].Width = second; Columns[2].Width = third;
                Columns[3].Width = width - first - second - third;
                if (IsHandleCreated) {
                    int offset = GetScrollPos(Handle,0);
                    if (offset != 0) SendMessage(Handle,0x1014,new IntPtr(-offset),IntPtr.Zero);
                }
                RefreshHeader();
                PositionNameEditor();
            } finally { fitting = false; }
        }
        public void SetPreferredColumns(int[] widths) {
            if (widths != null && widths.Length >= 3) preferred = new int[]{widths[0] < 80 ? 180 : widths[0],widths[1] < 80 ? 170 : widths[1],widths[2] < 60 ? 95 : widths[2]};
            FitColumns();
        }
        protected override void OnColumnWidthChanged(ColumnWidthChangedEventArgs e) {
            base.OnColumnWidthChanged(e);
            if (!fitting && Columns.Count == 4 && e.ColumnIndex < 3) {
                if (preferred == null) preferred = new int[]{Columns[0].Width,Columns[1].Width,Columns[2].Width};
                preferred[e.ColumnIndex] = Columns[e.ColumnIndex].Width;
                FitColumns();
            }
        }
        protected override void OnResize(EventArgs e) { base.OnResize(e); FitColumns(); }
        Rectangle NameTextBounds(ListViewItem item) {
            Rectangle cell = item.Bounds;
            cell.Width = Columns.Count > 0 ? Columns[0].Width : cell.Width;
            cell.X += 10; cell.Width = Math.Max(0,cell.Width-14);
            if (SmallImageList != null && item.ImageIndex >= 0 && item.ImageIndex < SmallImageList.Images.Count) {
                int offset = Math.Min(20,item.Bounds.Height-4)+8;
                cell.X += offset; cell.Width = Math.Max(0,cell.Width-offset);
            }
            return cell;
        }
        void PositionNameEditor() {
            if (editingItem == null || editorSurface == null || nameEditor == null || editingItem.ListView != this) return;
            Rectangle text = NameTextBounds(editingItem);
            editorSurface.SetBounds(text.Left,text.Top+1,Math.Max(8,text.Width),Math.Max(8,text.Height-2));
            int height = nameEditor.PreferredHeight;
            nameEditor.SetBounds(3,Math.Max(1,(editorSurface.Height-height)/2),Math.Max(1,editorSurface.Width-6),height);
        }
        protected override void OnBeforeLabelEdit(LabelEditEventArgs e) {
            base.OnBeforeLabelEdit(e);
            if (e.CancelEdit || e.Item < 0 || e.Item >= Items.Count) return;
            // Native label editing ignores the owner-drawn icon/text padding.
            // Keep the normal BeginEdit/F2 entry point, using one aligned editor.
            e.CancelEdit = true;
            ListViewItem item = Items[e.Item];
            BeginInvoke((MethodInvoker)delegate { if (!IsDisposed && item.ListView == this) BeginShortcutNameEdit(item); });
        }
        public void BeginShortcutNameEdit(ListViewItem item) {
            if (IsDisposed || Disposing || item == null || item.ListView != this) return;
            if (editingItem == item && nameEditor != null) { nameEditor.Focus(); return; }
            FinishShortcutNameEdit(false);
            item.EnsureVisible(); editingItem = item;
            editorSurface = new Panel { Name = "ShortcutNameEditorSurface", BackColor = BackColor, TabStop = false };
            editorSurface.Paint += delegate(object sender, PaintEventArgs args) {
                Panel surface = (Panel)sender;
                using (Pen border = new Pen(AccentColor)) args.Graphics.DrawRectangle(border,0,0,Math.Max(0,surface.Width-1),Math.Max(0,surface.Height-1));
            };
            nameEditor = new TextBox { Name = "ShortcutNameEditor", AccessibleName = "Future desktop shortcut name", BorderStyle = BorderStyle.None, Font = Font, BackColor = BackColor, ForeColor = ForeColor, Text = item.Text };
            nameEditor.KeyDown += delegate(object sender, KeyEventArgs args) {
                if (args.KeyCode != Keys.Enter && args.KeyCode != Keys.Escape) return;
                args.Handled = true; args.SuppressKeyPress = true;
                FinishShortcutNameEdit(args.KeyCode == Keys.Escape); Focus();
            };
            nameEditor.LostFocus += delegate { FinishShortcutNameEdit(false); };
            editorSurface.Controls.Add(nameEditor); Controls.Add(editorSurface);
            PositionNameEditor(); editorSurface.BringToFront();
            Invalidate(item.Bounds); nameEditor.Focus(); nameEditor.SelectAll();
        }
        void FinishShortcutNameEdit(bool cancel) {
            if (editingItem == null) return;
            ListViewItem item = editingItem; string text = nameEditor == null ? item.Text : nameEditor.Text;
            Panel surface = editorSurface;
            editingItem = null; nameEditor = null; editorSurface = null;
            if (surface != null) { Controls.Remove(surface); surface.Dispose(); }
            if (!cancel && item.ListView == this && !IsDisposed && !Disposing) {
                LabelEditEventArgs result = new LabelEditEventArgs(item.Index,text);
                base.OnAfterLabelEdit(result);
                if (!result.CancelEdit) item.Text = text;
            }
            if (!IsDisposed && !Disposing) Invalidate();
        }
        protected override void WndProc(ref Message message) {
            // Finish editing before scrolling or programmatically replacing rows.
            if (message.Msg == 0x0115 || message.Msg == 0x020A || message.Msg == 0x1009) FinishShortcutNameEdit(false);
            base.WndProc(ref message);
        }
        protected override void OnDrawColumnHeader(DrawListViewColumnHeaderEventArgs e) {
            using (Brush brush = new SolidBrush(HeaderColor)) e.Graphics.FillRectangle(brush, e.Bounds);
            using (Pen line = new Pen(DividerColor)) e.Graphics.DrawLine(line, e.Bounds.Left, e.Bounds.Bottom-1, e.Bounds.Right, e.Bounds.Bottom-1);
            using (Pen line = new Pen(DividerColor)) e.Graphics.DrawLine(line, e.Bounds.Right-1, e.Bounds.Top+4, e.Bounds.Right-1, e.Bounds.Bottom-5);
            Rectangle text = e.Bounds; text.X += 10; text.Width = Math.Max(0, text.Width - 14);
            TextRenderer.DrawText(e.Graphics, e.Header.Text, Font, text, MutedColor, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
        }
        protected override void OnDrawItem(DrawListViewItemEventArgs e) { if (View != View.Details) base.OnDrawItem(e); }
        protected override void OnDrawSubItem(DrawListViewSubItemEventArgs e) {
            bool selected = e.Item.Selected;
            Color background = selected ? SelectionColor : BackColor;
            using (Brush brush = new SolidBrush(background)) e.Graphics.FillRectangle(brush, e.Bounds);
            Rectangle text = e.Bounds; text.X += 10; text.Width = Math.Max(0, text.Width - 14);
            if (e.ColumnIndex == 0) {
                if (selected) using (Brush marker = new SolidBrush(AccentColor)) e.Graphics.FillRectangle(marker, e.Bounds.Left, e.Bounds.Top + 3, 2, Math.Max(0, e.Bounds.Height - 6));
                if (SmallImageList != null && e.Item.ImageIndex >= 0 && e.Item.ImageIndex < SmallImageList.Images.Count) {
                    int size = Math.Min(20, e.Bounds.Height-4);
                    e.Graphics.DrawImage(SmallImageList.Images[e.Item.ImageIndex], new Rectangle(text.X, e.Bounds.Top + (e.Bounds.Height-size)/2, size, size));
                    text.X += size + 8; text.Width = Math.Max(0, text.Width-size-8);
                }
            }
            Color foreground = e.ColumnIndex == 0 || selected ? ForeColor : MutedColor;
            if (e.ColumnIndex != 0 || e.Item != editingItem) {
                TextRenderer.DrawText(e.Graphics, e.SubItem.Text, Font, text, foreground, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
            } else { PositionNameEditor(); }
            if (selected && Focused && e.ColumnIndex == Columns.Count-1) {
                Rectangle focus = e.Item.Bounds; focus.Width = Math.Max(0, ClientSize.Width-2); focus.Height -= 1;
                using (Pen pen = new Pen(AccentColor)) { pen.DashStyle = DashStyle.Dot; e.Graphics.DrawRectangle(pen, focus); }
            }
        }
    }
    public class FieldSurface : Panel {
        public Color BorderColor { get; set; }
        public Color FocusColor { get; set; }
        public FieldSurface() {
            SetStyle(ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            Padding = new Padding(9,7,9,5); BorderColor = Color.FromArgb(68,71,90); FocusColor = Color.FromArgb(98,114,164);
        }
        protected override void OnControlAdded(ControlEventArgs e) {
            base.OnControlAdded(e); e.Control.Enter += delegate { Invalidate(); }; e.Control.Leave += delegate { Invalidate(); };
        }
        protected override void OnPaint(PaintEventArgs e) {
            base.OnPaint(e);
            using (Pen pen = new Pen(ContainsFocus ? FocusColor : BorderColor, ContainsFocus ? 2 : 1)) {
                e.Graphics.DrawRectangle(pen, 1,1,Math.Max(0,Width-3),Math.Max(0,Height-3));
            }
        }
    }
    public class ThemedCheckBox : CheckBox {
        public Color AccentColor { get; set; }
        public Color MutedColor { get; set; }
        public ThemedCheckBox() {
            SetStyle(ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            AccentColor = Color.FromArgb(98,114,164); MutedColor = Color.FromArgb(150,150,150);
        }
        protected override void OnCheckedChanged(EventArgs e) { base.OnCheckedChanged(e); Invalidate(); }
        protected override void OnPaint(PaintEventArgs e) {
            e.Graphics.Clear(BackColor);
            float scale = e.Graphics.DpiX / 96f;
            int size = Math.Max(14,(int)Math.Round(14*scale)), y = (Height-size)/2;
            Rectangle box = new Rectangle((int)scale,y,size,size);
            using (Brush fill = new SolidBrush(Checked ? AccentColor : BackColor)) e.Graphics.FillRectangle(fill,box);
            using (Pen border = new Pen(Checked || Focused ? AccentColor : MutedColor)) e.Graphics.DrawRectangle(border,box);
            if (Checked) using (Pen mark = new Pen(BackColor,2*scale)) e.Graphics.DrawLines(mark,new Point[]{new Point((int)(4*scale),y+(int)(7*scale)),new Point((int)(7*scale),y+(int)(10*scale)),new Point((int)(12*scale),y+(int)(4*scale))});
            int offset = (int)(23*scale);
            Rectangle text = new Rectangle(offset,0,Math.Max(0,Width-offset),Height);
            TextRenderer.DrawText(e.Graphics,Text,Font,text,Enabled ? ForeColor : MutedColor,TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis);
            if (Focused) ControlPaint.DrawFocusRectangle(e.Graphics,text,AccentColor,BackColor);
        }
    }
    public class MenuColors : ProfessionalColorTable {
        Color surface, selection, border;
        public MenuColors(Color background, Color selected, Color edge) { surface = background; selection = selected; border = edge; UseSystemColors = false; }
        public override Color ToolStripDropDownBackground { get { return surface; } }
        public override Color ImageMarginGradientBegin { get { return surface; } }
        public override Color ImageMarginGradientMiddle { get { return surface; } }
        public override Color ImageMarginGradientEnd { get { return surface; } }
        public override Color MenuItemSelected { get { return selection; } }
        public override Color MenuItemBorder { get { return selection; } }
        public override Color MenuBorder { get { return border; } }
        public override Color SeparatorDark { get { return border; } }
        public override Color SeparatorLight { get { return border; } }
    }
}
'@ -ErrorAction Stop
}

function New-AppTextField {
